using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Instructor> _instructors;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments =
        [
            new() { Id = 1, Code = "CS", Name = "Computer Science", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Code = "MATH", Name = "Mathematics", Description = "Study of numbers, quantities, shapes, and patterns." },
            new() { Id = 3, Code = "ENG", Name = "English", Description = "Study of literature, writing, and communication." },
            new() { Id = 4, Code = "PHYS", Name = "Physics", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = 5, Code = "HIST", Name = "History", Description = "Study of past events and human civilization." },
        ];

        _instructors =
        [
            new() { Id = 1, Name = "Dr. Ada Lovelace", Title = "Professor", Bio = "Specializes in algorithms and programming language theory. Published over 40 papers on computational complexity.", Email = "alovelace@university.edu" },
            new() { Id = 2, Name = "Dr. Alan Turing", Title = "Associate Professor", Bio = "Expert in artificial intelligence and machine learning. Leads the university AI research lab.", Email = "aturing@university.edu" },
            new() { Id = 3, Name = "Dr. Emmy Noether", Title = "Professor", Bio = "Renowned mathematician focused on abstract algebra and theoretical physics applications.", Email = "enoether@university.edu" },
            new() { Id = 4, Name = "Dr. William Shakespeare", Title = "Professor", Bio = "Award-winning author and literary critic specializing in Renaissance literature and creative writing.", Email = "wshakespeare@university.edu" },
            new() { Id = 5, Name = "Dr. Marie Curie", Title = "Professor", Bio = "Pioneering researcher in nuclear physics and radiation studies. Two-time Nobel Prize laureate.", Email = "mcurie@university.edu" },
            new() { Id = 6, Name = "Dr. Herodotus", Title = "Associate Professor", Bio = "Historian specializing in ancient civilizations and comparative world history.", Email = "herodotus@university.edu" },
        ];

        _courses =
        [
            new() { Id = 1, Code = "CS 101", Title = "Introduction to Computer Science", Description = "A broad introduction to computer science covering problem solving, programming fundamentals in Python, data representation, and an overview of computer systems. No prior experience required.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", Location = "Science Hall 201", DepartmentId = 1, Department = _departments[0], Instructor = _instructors[0], IsFeatured = true },
            new() { Id = 2, Code = "CS 201", Title = "Data Structures and Algorithms", Description = "Study of fundamental data structures (arrays, linked lists, trees, graphs, hash tables) and algorithm design techniques (divide and conquer, dynamic programming, greedy algorithms). Includes complexity analysis.", Credits = 4, Schedule = "Tue/Thu 10:30 AM–12:00 PM", Location = "Science Hall 305", DepartmentId = 1, Department = _departments[0], Instructor = _instructors[0] },
            new() { Id = 3, Code = "CS 330", Title = "Artificial Intelligence", Description = "Foundations of AI including search algorithms, knowledge representation, machine learning basics, natural language processing, and ethical considerations in AI development.", Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", Location = "Tech Building 110", DepartmentId = 1, Department = _departments[0], Instructor = _instructors[1], IsFeatured = true },
            new() { Id = 4, Code = "CS 450", Title = "Software Engineering", Description = "Principles and practices of software engineering including requirements analysis, system design, testing strategies, agile methodologies, and team-based project development.", Credits = 3, Schedule = "Tue/Thu 1:00–2:20 PM", Location = "Tech Building 215", DepartmentId = 1, Department = _departments[0], Instructor = _instructors[1] },
            new() { Id = 5, Code = "MATH 101", Title = "Calculus I", Description = "Limits, continuity, derivatives of single-variable functions, applications of differentiation, introduction to integration, and the Fundamental Theorem of Calculus.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", Location = "Math Building 101", DepartmentId = 2, Department = _departments[1], Instructor = _instructors[2], IsFeatured = true },
            new() { Id = 6, Code = "MATH 201", Title = "Linear Algebra", Description = "Vector spaces, matrices, determinants, eigenvalues and eigenvectors, linear transformations, and applications to systems of equations and geometry.", Credits = 3, Schedule = "Tue/Thu 9:00–10:20 AM", Location = "Math Building 203", DepartmentId = 2, Department = _departments[1], Instructor = _instructors[2] },
            new() { Id = 7, Code = "MATH 310", Title = "Probability and Statistics", Description = "Probability theory, random variables, distributions, hypothesis testing, confidence intervals, and regression analysis with real-world applications.", Credits = 3, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", Location = "Math Building 105", DepartmentId = 2, Department = _departments[1], Instructor = _instructors[2] },
            new() { Id = 8, Code = "ENG 101", Title = "Composition and Rhetoric", Description = "Development of college-level writing skills through analytical reading, critical thinking, and the composition of essays in various rhetorical modes.", Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", Location = "Humanities Hall 102", DepartmentId = 3, Department = _departments[2], Instructor = _instructors[3] },
            new() { Id = 9, Code = "ENG 250", Title = "World Literature", Description = "Survey of major literary works from diverse cultures and historical periods, exploring themes of identity, power, and the human condition.", Credits = 3, Schedule = "Tue/Thu 2:00–3:20 PM", Location = "Humanities Hall 210", DepartmentId = 3, Department = _departments[2], Instructor = _instructors[3], IsFeatured = true },
            new() { Id = 10, Code = "PHYS 101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Covers Newton's laws, energy, momentum, rotational dynamics, oscillations, and introduction to fluid mechanics. Lab included.", Credits = 4, Schedule = "Mon/Wed/Fri 8:00–8:50 AM + Lab Thu 2:00–4:50 PM", Location = "Physics Lab 101", DepartmentId = 4, Department = _departments[3], Instructor = _instructors[4] },
            new() { Id = 11, Code = "PHYS 201", Title = "General Physics II", Description = "Electricity, magnetism, optics, and modern physics. Covers electrostatics, circuits, electromagnetic waves, interference, diffraction, and introduction to quantum mechanics. Lab included.", Credits = 4, Schedule = "Mon/Wed/Fri 9:00–9:50 AM + Lab Tue 2:00–4:50 PM", Location = "Physics Lab 102", DepartmentId = 4, Department = _departments[3], Instructor = _instructors[4], IsFeatured = true },
            new() { Id = 12, Code = "HIST 101", Title = "World History to 1500", Description = "Survey of world civilizations from prehistory through the Renaissance, examining political, social, economic, and cultural developments across continents.", Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:20 PM", Location = "Liberal Arts 305", DepartmentId = 5, Department = _departments[4], Instructor = _instructors[5] },
            new() { Id = 13, Code = "HIST 202", Title = "Modern World History", Description = "Examination of global developments from the Enlightenment to the present, including industrialization, imperialism, world wars, decolonization, and globalization.", Credits = 3, Schedule = "Mon/Wed 3:30–4:50 PM", Location = "Liberal Arts 310", DepartmentId = 5, Department = _departments[4], Instructor = _instructors[5] },
        ];
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.Find(d => d.Id == id);

    public List<Course> GetCourses(string? search = null, int? departmentId = null, int? credits = null)
    {
        IEnumerable<Course> query = _courses;

        if (departmentId.HasValue)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (credits.HasValue)
            query = query.Where(c => c.Credits == credits.Value);

        if (!string.IsNullOrWhiteSpace(search))
        {
            var term = search.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public Course? GetCourse(int id) => _courses.Find(c => c.Id == id);

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public List<int> GetDistinctCredits() => _courses.Select(c => c.Credits).Distinct().Order().ToList();

    public bool SubmitEnrollmentRequest(EnrollmentRequest request)
    {
        var course = GetCourse(request.CourseId);
        return course is not null
            && !string.IsNullOrWhiteSpace(request.StudentName)
            && !string.IsNullOrWhiteSpace(request.StudentId);
    }
}

